import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"十三元","description":"","frontmatter":{"title":"十三元","date":"2026-11-17T00:00:00.000Z","seq":13,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/十三元.md","filePath":"blogs/声律启蒙·上卷/十三元.md"}'),r={name:"blogs/声律启蒙·上卷/十三元.md"};function p(_,e,l,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="十三元" tabindex="-1">十三元 <a class="header-anchor" href="#十三元" aria-label="Permalink to &quot;十三元&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">幽对显，寂对喧，柳岸对桃源。莺朋对燕友，早暮对寒暄。鱼跃沼，鹤乘轩，醉胆对吟魂。轻尘生范甑，积雪拥袁门。缕缕轻烟芳草渡，丝丝微雨杏花村。诣阙王通，献太平十二策；出关老子，著道德五千言。</p><p class="poem-stanza">儿对女，子对孙，药圃对花村。高楼对邃阁，赤豹对玄猿。妃子骑，夫人轩，旷野对平原。匏巴能鼓瑟，伯氏善吹埙。馥馥早梅思驿使，萋萋芳草怨王孙。秋夕月明，苏子黄岗游绝壁；春朝花发，石家金谷启芳园。</p><p class="poem-stanza">歌对舞，德对恩，犬马对鸡豚。龙池对凤沼，雨骤对云屯。刘向阁，李膺门，唳鹤对啼猿。柳摇春白昼，梅弄月黄昏，岁冷松筠皆有节，春喧桃李本无言。噪晚齐蝉，岁岁秋来泣恨；啼宵蜀鸟，年年春去伤魂。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
